; String table: 31 little-endian pointers, ROM $BA18-$BA55, runtime $1670-$16AD.
;
; This is how the text is reached - nothing addresses a record directly, which is
; why searching for pointers to the visible strings came up empty. Each entry
; points at a record header, not at the text:
;
;     [0] $11F8  18 00 C0 01 98  "von Diskette: File? "
;     [3] $126B  2C 00 C0 01 98  "Load Capture Display Macro Xfer Screen  "
;     [4] $1298  2C 00 C0 01 98  "ASCII Btx Keybd Telesoft Edit Pause Quit"
;
; A record is five header bytes followed by the text. Header byte 0 is the record
; length minus one, which is what makes the stride vary: $2C gives a 45-byte
; record with 40 characters, $18 a 25-byte record with 20, $04 a 5-byte record
; with none. Byte 1 is always $00 and byte 4 always $98; bytes 2 and 3 vary
; ($C0/$80, $01/$07) and look like display parameters, not yet established.
;
; The earlier reading of these five bytes as a trailer was wrong - they lead the
; record, and the pointers here prove it.
c64StrTable:
        DW      L11F8,L1211,L123E,L126B,L1298,L12C5,L12F2,L131F
        DW      L1338,L1351,L1356,L1383,L13A2,L13AD,L13DA,L13F3
        DW      L140A,L1437,L1464,L1491,L14BE,L14EB,L1507,L151B
        DW      L1548,L1575,L15A2,L15BB,L15E9,L1616,L1643

c64ColdStart:
; vector 0 $1000 - cold start: IOINIT/RESTOR/PCINT/INITCZ/CLALL, clear zero page, hook CINV to the decoder IRQ, enable the decoder interrupt
        LDA     #$00
        STA     $D016
        JSR     IOINIT
        LDA     #$00
        TAY

L16B9:
        STA     >$0002,Y
        STA     BUF,Y
        STA     IERROR,Y
        INY
        BNE     L16B9
        JSR     SIZE+8
        JSR     RESTOR
        JSR     PCINT
        JSR     INITCZ
        JSR     CLALL
        LDA     #$00
        STA     btxFifo00
        STA     btxFifo0B
        SEI
        LDA     #L2359&255
        STA     CINV
        LDA     #L2359>>8
        STA     CINV+1
        LDA     btxReg1F9
        LDA     #$40
        STA     btxReg1F8
        LDA     btxReg1FD
        STA     btxReg1FD
        LDA     btxReg1FC
        STA     btxReg1FC
        CLI
        JSR     L2404

c64StartSession:
; vector 1 $1003 - show the splash, send ceptStartPage to the decoder, reset the capture-buffer pointers and mode flags
        JSR     vecShowSplash
        LDA     btxReg012
        BNE     L172D
        LDA     #$FF
        STA     btxReg012
        LDA     c64StartPagePtr
        STA     c64Ptr
        LDA     c64StartPagePtr+1
        STA     c64PtrHi
        LDA     #$FF
        STA     btxReg00F

