L172D:
        LDA     c64BufStart
        STA     c64CapEnd
        LDA     c64BufStart+1
        STA     c64CapEnd+1
        LDA     #$00
        STA     L11D9
        STA     L11EC
        LDA     #$00
        STA     L11E8
        STA     L11D8
        STA     L11F7

c64MainLoop:
; vector 2 $1006 - main loop: fetch a key, STOP ends a capture, F7 ($88) opens the menu, anything else goes to c64SendKey
        LDA     #$FF
        STA     btxReg00F

L1751:
        SEI
        LDA     L11E9
        CLI
        BIT     L11D9
        BPL     L175E
        JSR     vecCaptureRun

L175E:
        JSR     vecGetKey
        BCS     L1751
        CMP     #$03
        BNE     L176D
        JSR     vecCaptureEnd
        JMP     L177F

L176D:
        CMP     #$88
        BNE     L177C
        BIT     L11D9
        BMI     L177C
        JSR     vecMenu
        JMP     L177F

L177C:
        JSR     vecSendKey

L177F:
        JMP     L1751

c64SendKey:
; vector 3 $1009 - translate one key with c64XlatKey and send the resulting 1-3 CEPT bytes to the decoder
        CMP     #$8B
        BNE     L1789
        JSR     vecCaptureEnd

L1789:
        CMP     #$8C
        BNE     L1790
        JSR     vecCaptureEnd

L1790:
        JSR     vecXlatKey
        BCS     L17B5
        LDA     L11F7
        BEQ     L179F
        LDA     L11E9
        BMI     L17B5

L179F:
        LDA     L11E9
        JSR     vecSendByte
        LDA     L11EA
        BEQ     L17AD
        JSR     vecSendByte

L17AD:
        LDA     L11EB
        BEQ     L17B5
        JSR     vecSendByte

L17B5:
        RTS

c64XlatKey:
; vector 5 $100F - PETSCII key -> CEPT, via c64AsciiKeys (2-byte records, alpha mode), then c64GermanKeys, then c64CtrlKeys (4-byte records). C=1 when the key has no mapping
        LDX     #$00
        STX     L11E9
        STX     L11EA
        STX     L11EB
        LDX     L11E8
        BEQ     L180D
        LDX     L11F7
        BEQ     L17EF
        LDX     #c64AsciiKeys&255
        STX     c64KeyPtr
        LDX     #c64AsciiKeys>>8
        STX     c64KeyPtrHi
        LDY     #$00

L17D5:
        TAX
        LDA     (c64KeyPtr),Y
        BEQ     L17EE
        TXA
        CMP     (c64KeyPtr),Y
        BEQ     L17E4
        INY
        INY
        JMP     L17D5

L17E4:
        INY
        LDA     (c64KeyPtr),Y
        BEQ     L185B
        STA     L11E9
        CLC
        RTS

L17EE:
        TXA

L17EF:
        LDX     c64GermanKeysPtr
        STX     c64KeyPtr
        LDX     c64GermanKeysPtr+1
        STX     c64KeyPtrHi
        LDY     #$00

L17FB:
        TAX
        LDA     (c64KeyPtr),Y
        BEQ     L180C
        TXA
        CMP     (c64KeyPtr),Y
        BEQ     L185D
        INY
        INY
        INY
        INY
        JMP     L17FB

L180C:
        TXA

L180D:
        LDX     c64CtrlKeysPtr
        STX     c64KeyPtr
        LDX     c64CtrlKeysPtr+1
        STX     c64KeyPtrHi
        LDY     #$00

L1819:
        TAX
        LDA     (c64KeyPtr),Y
        BEQ     L182A
        TXA
        CMP     (c64KeyPtr),Y
        BEQ     L185D
        INY
        INY
        INY
        INY
        JMP     L1819

L182A:
        TXA
        CMP     #$00
        BEQ     L184F
        CMP     #$10
        BEQ     L185B
        CMP     #$20
        BCC     L184F
        CMP     #$41
        BCC     L184F
        CMP     #$5B
        BCC     L184D
        CMP     #$60
        BCC     L184F
        CMP     #$C1
        BCC     L185B
        CMP     #$DB
        BCC     L1854
        BCS     L185B

L184D:
        ORA     #$20

L184F:
        STA     L11E9
        CLC
        RTS

L1854:
        AND     #$7F
        STA     L11E9
        CLC
        RTS

L185B:
        SEC
        RTS

L185D:
        INY
        LDA     (c64KeyPtr),Y
        STA     L11E9
        INY
        LDA     (c64KeyPtr),Y
        STA     L11EA
        INY
        LDA     (c64KeyPtr),Y
        STA     L11EB
        CLC
        RTS

; Character table, runtime $1871-$188E, sitting straight after an RTS so a
; linear sweep runs into it and disassembles the bytes as instructions.
;
;     23 40 3B 7B 3A 7C 40 7D 2B 7E 5D 5B 5B 5C BA 5D 2D
;     00 DD 00 5E 00 DE 00 5C 00 A9 00 00 00
;
; The first run is # @ ; { : | @ } + ~ ] [ [ \ : ] - which are precisely the
; positions where the German and ASCII keyboard layouts differ - the same choice
; the "Keyboard: deutsch oder ASCII?" prompt offers. The tail pairs each $00 with
; a high-bit code ($DD, $DE, $A9), which look like the PETSCII characters those
; positions map to.
;
; Read as a layout translation table on that basis, and the code confirms the
; shape: $17D2 points c64KeyPtr here and then walks it with
;
;     LDA (c64KeyPtr),Y / BEQ done      $00 ends the table
;     TXA / CMP (c64KeyPtr),Y / BEQ hit
;     INY / INY                       two bytes per entry
;
; so it is a two-byte-per-entry lookup terminated by $00. Which byte is the
; input and which the output is not established, and the pairing across the
; whole table has not been decoded.
c64AsciiKeys:
        FCC     "#@;{:|@}+~][["
        FCB     $5C,$BA,$5D,$2D,$00,$DD,$00,$5E,$00,$DE,$00,$5C,$00,$A9,$00,$00
        FCB     $00

c64SendByte:
; vector 6 $1012 - push A into the 64-byte C64->decoder ring at btxReg040, spinning while it is full, then run c64CtrlThrottle
        LDX     btxXferDone
        CPX     btxXferDone
        BNE     c64SendByte
        CPX     #$00
        BEQ     c64SendByte

L189B:
        LDX     btxReg00D
        INX
        CPX     #$40
        BNE     L18A5
        LDX     #$00

L18A5:
        CPX     btxReg00E
        BEQ     L189B
        CPX     btxReg00E
        BEQ     L189B
        LDY     btxReg00D
        STA     btxReg040,Y
        STX     btxReg00D
        JSR     vecCtrlThrottle
        RTS

c64GetByteWait:
; vector 7 $1015 - c64GetByte in a loop: block until the decoder delivers a byte
        JSR     vecGetByte
        BCS     c64GetByteWait
        RTS

c64GetByte:
; vector 8 $1018 - pull one byte from the 32-byte decoder->C64 ring at btxReg020. C=1 when empty. Read pointers twice to ride out metastability
        LDA     btxFifoRd
        CMP     btxFifoWr
        BEQ     L18CF
        CMP     btxFifoWr
        BNE     L18D1

L18CF:
        SEC
        RTS

L18D1:
        TAX
        LDA     btxReg020,X
        INX
        CPX     #$20
        BNE     L18DC
        LDX     #$00

L18DC:
        STX     btxFifoRd
        CLC
        RTS

c64HideMsg:
; vector 9 $101B - send $10 $7A $10 $55: close the status-line overlay and put the BTX page back
        LDA     #$10
        JSR     vecSendByte
        LDA     #$7A
        JSR     vecSendByte
        LDA     #$10
        JSR     vecSendByte
        LDA     #$55
        JSR     vecSendByte
        RTS

c64CaptureEnd:
; vector 10 $101E - STOP during a capture: send $10 $6D, wait for the transfer to drain, record the end pointer and offer c64SaveBuffer
        BIT     L11D9
        BPL     L192F
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6D
        JSR     vecSendByte
        LDA     #$00
        STA     L11D9

L190A:
        LDA     btxXferEn
        BNE     L190A
        LDA     btxXferEn
        BNE     L190A
        JSR     vecCaptureRun
        JSR     vecClearMsg
        LDA     c64BufWr
        STA     c64CapEnd
        LDA     c64BufWrHi
        STA     c64CapEnd+1
        LDA     #$07
        JSR     vecShowMsg
        JSR     vecSaveBuffer
        JSR     vecHideMsg

L192F:
        RTS

c64CtrlThrottle:
; vector 11 $1021 - poll keyboard row 7 for CTRL ($DC01 = $FB) and burn ~2000 cycles while it is held: the classic hold-to-slow-output
        LDA     #$7F
        STA     $DC00
        LDA     $DC01
        CMP     #$FB
        PHP
        LDA     #$7F
        STA     $DC00
        PLP
        BNE     L194D
        LDX     #$0A

L1945:
        LDY     #$C8

L1947:
        DEY
        BNE     L1947
        DEX
        BNE     L1945

L194D:
        RTS

c64Menu:
; vector 4 $100C - the <F7> menu: shows msg 3/4, reads a letter and dispatches through c64MenuKeys; any other key toggles the two menu lines
        LDA     #$00
        STA     L11E7

L1953:
        LDA     #$03
        LDX     L11E7
        BEQ     L195C
        LDA     #$04

L195C:
        JSR     vecShowMsg

L195F:
        JSR     vecGetKey
        AND     #$7F
        BEQ     L195F
        CMP     #$03
        BNE     L196D
        JMP     vecHideMsg

L196D:
        STA     L11B9
        LDY     #$FD

L1972:
        INY
        INY
        INY
        LDA     c64MenuKeys,Y
        BEQ     L198C
        CMP     L11B9
        BNE     L1972
        LDA     c64MenuKeys+1,Y
        STA     c64Ptr
        LDA     c64MenuKeys+2,Y
        STA     c64PtrHi
        JMP     (c64Ptr)

L198C:
        LDA     L11E7
        EOR     #$FF
        STA     L11E7
        JMP     L1953

; Menu key dispatch: records of one ASCII key byte then a 16-bit handler
; address, terminated by $00.
;
;     'L' -> $102D    'C' -> $103C    'D' -> $1042    'M' -> $1039
;     'X' -> $1045    'A' -> $1024    'B' -> $1027    'S' -> $1048
;     'K' -> $104E    'P' -> $1051    'E' -> $1054    'Q' -> $102A
;     'T' -> $10AB
;
; The keys are the highlighted letters of the two menu lines - "Load Capture
; Display Macro Xfer Screen" and "ASCII Btx Keybd Telesoft Edit Pause Quit" -
; and every target is an entry in the jump table at $1000, so this is what turns
; a keypress into a command.
c64MenuKeys:
        FCB     $4C                    ; 'L'
        DW      vecMenuLoad
        FCB     $43                    ; 'C'
        DW      vecMenuCapture
        FCB     $44                    ; 'D'
        DW      vecMenuDisplay
        FCB     $4D                    ; 'M'
        DW      vecMenuMacro
        FCB     $58                    ; 'X'
        DW      vecMenuXfer
        FCB     $41                    ; 'A'
        DW      vecMenuAscii
        FCB     $42                    ; 'B'
        DW      vecMenuBtx
        FCB     $53                    ; 'S'
        DW      vecMenuScreen
        FCB     $4B                    ; 'K'
        DW      vecMenuKeybd
        FCB     $50                    ; 'P'
        DW      vecMenuPause
        FCB     $45                    ; 'E'
        DW      vecMenuEdit
        FCB     $51                    ; 'Q'
        DW      vecMenuQuit
        FCB     $54                    ; 'T'
        DW      vecMenuTelesoft
        FCB     $00

c64MenuAscii:
; vector 12 $1024 - menu 'A' (ASCII): send $10 $67 and set the alpha-mode flag, which adds c64AsciiKeys to the front of c64XlatKey's search chain
        LDA     #$10
        JSR     vecSendByte
        LDA     #$67
        JSR     vecSendByte
        LDA     #$FF
        STA     L11F7
        RTS

c64MenuBtx:
; vector 13 $1027 - menu 'B' (Btx): send $10 $66 and clear the alpha-mode flag
        LDA     #$10
        JSR     vecSendByte
        LDA     #$66
        JSR     vecSendByte
        LDA     #$00
        STA     L11F7
        RTS

c64MenuQuit:
; vector 14 $102A - menu 'Q' (Quit): send ceptMonitorMsg ("C-64 - Betrieb ... Monitor an den Rechner umstecken"), close the drive command channel and JMP (KERNAL_RESET)
        JSR     vecHideMsg
        LDA     #$00
        STA     btxFifo00
        LDA     #$10
        JSR     vecSendByte
        LDA     #$4C
        JSR     vecSendByte
        LDA     #$10
        JSR     vecSendByte
        LDA     #$66
        JSR     vecSendByte
        LDA     #$41
        STA     c64Ptr
        LDA     #$1A
        STA     c64PtrHi

L1A03:
        LDY     #$00
        LDA     (c64Ptr),Y
        BEQ     L1A15
        JSR     vecSendByte
        INC     c64Ptr
        BNE     L1A03
        INC     c64PtrHi
        JMP     L1A03

L1A15:
        LDA     #$02
        JSR     vecDelaySecs
        LDA     #$10
        JSR     vecSendByte
        LDA     #$51
        JSR     vecSendByte
        LDA     #$02
        JSR     vecDelaySecs
        JSR     UNLSN
        LDA     #$08
        JSR     LISTN
        LDA     #$EF
        JSR     SECND
        JSR     UNLSN
        LDA     #$00
        STA     btxReg005
        JMP     (KERNAL_RESET)

; CEPT datastream, not C64 screen text.
;
; The payload composes pages in the decoder's own protocol and sends them across
; rather than drawing on the C64 screen, so these blocks read as control codes
; mixed with text:
;
;     $1F r c   US, then row and column - CEPT cursor positioning
;     $9B ...   CSI, the C1 introducer the firmware dispatches at $D289
;     $1B ...   ESC, dispatched at $D1C9
;     $12 c n   RPT, repeat a character - ctlRPT at $DB2B in the firmware
;
; Three of them exist:
;
;   ceptMonitorMsg  $BDE9  "C-64 - Betrieb", then positioned lines
;                          "falls noetig,", "Monitor an den Rechner",
;                          "umstecken"
;   ceptMacroDir    $CD17  "Makro-Verzeichnis"
;   ceptStartPage   $CF65  the startup page: "commodore" in text followed by
;                          G1 mosaic characters ($A0-$DF) drawn with RPT runs,
;                          which is why it looks like noise as bytes. It ends
;                          with "V1.6 141087wr" - the C64 payload's own version
;                          and a date, 14 October 1987, plus what look like
;                          author initials. That is a different version line
;                          from the firmware's "Decodersoftware V3.3" at $EFF5,
;                          so the two halves are versioned separately.
;
; That the C64 side speaks CEPT to the decoder is what makes ctlRPT and the
; mosaic set visible from both directions - the firmware decodes exactly what
; this data encodes.
ceptMonitorMsg:
        FCB     $1F,$2F,$41,$9B,$31,$40,$1B,$23,$20,$57,$9B,$30,$40,$1F
        FCC     "EA   "
        FCB     $8F,$08
        FCC     " C-64 - Betrieb"
        FCB     $1F
        FCC     "KNfalls n"
        FCB     $C8
        FCC     "otig,"
        FCB     $1F
        FCC     "MIMonitor an den Rechner"
        FCB     $1F
        FCC     "OOumstecken"
        FCB     $00

c64MenuLoad:
; vector 15 $102D - menu 'L' (Load): msg 0 "von Diskette: File?", then stream the file to the decoder through c64DiskOpenRead/GetByte/CloseRead
        JSR     vecClearMsg
        LDA     #$00
        JSR     vecShowMsg
        LDA     #$13
        JSR     vecInputLine
        BCC     L1AAE
        JSR     vecHideMsg
        RTS

L1AAE:
        JSR     vecDiskOpenRead
        BCC     L1AC1
        LDA     #$02
        JSR     vecShowMsg

L1AB8:
        JSR     vecGetKey
        BCS     L1AB8
        JSR     vecHideMsg
        RTS

L1AC1:
        TXA
        PHA
        LDA     #$10
        JSR     vecSendByte
        LDA     #$4C
        JSR     vecSendByte
        PLA
        CMP     #$10
        BEQ     L1AD5
        JSR     vecSendByte

L1AD5:
        JSR     vecDiskGetByte
        BCS     L1B05
        CMP     #$10
        BEQ     L1AF0
        PHA
        JSR     vecSendByte
        PLA
        CMP     #$11
        BNE     L1AF0
        BIT     STATUS
        BVS     L1AF0
        LDA     #$05
        JSR     vecDelaySecs

L1AF0:
        BIT     STATUS
        BVC     L1AD5

L1AF4:
        JSR     vecDiskCloseRead
        JSR     vecHideMsg
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6C
        JSR     vecSendByte
        RTS

L1B05:
        BIT     L11EC
        BPL     L1AF4
        JSR     vecMacroCloseRead
        LDA     #$00
        STA     L11EC
        LDA     #$10
        JSR     vecSendByte
        LDA     #$2E
        JSR     vecSendByte
        JSR     vecHideMsg
        JMP     L1AF4

c64MenuMacro:
; vector 19 $1039 - menu 'M' (Macro): msg $0B, read a macro id ('0'-'9','A'-'Z') or '?' for c64MacroDir, then send $08 $20 <id> $00 to the decoder and play the macro back
        LDA     #$00
        STA     STATUS
        LDA     #$08
        JSR     LISTN
        BIT     STATUS
        BMI     L1B38
        LDA     #$6F
        JSR     SECND
        BIT     STATUS
        BPL     L1B4B

L1B38:
        LDA     #$0D
        JSR     vecShowMsg
        LDA     #$17
        JSR     vecShowMsg

L1B42:
        JSR     vecGetKey
        BCS     L1B42
        JSR     vecHideMsg
        RTS

L1B4B:
        JSR     UNLSN
        JSR     vecDiskCheckError
        JSR     vecClearMsg
        LDA     #$0B
        JSR     vecShowMsg

L1B59:
        JSR     vecGetKey
        CMP     #$03
        BNE     L1B69
        LDA     #$00
        JSR     vecSendByte
        JSR     vecHideMsg
        RTS

L1B69:
        CMP     #$3F
        BEQ     L1B71
        CMP     #$DB
        BNE     L1B7C

L1B71:
        LDA     #$00
        JSR     vecSendByte
        JSR     vecMacroDir
        JMP     vecMenuMacro

L1B7C:
        CMP     #$30
        BCC     L1B59
        CMP     #$3A
        BCC     L1B8E
        AND     #$7F
        CMP     #$41
        BCC     L1B59
        CMP     #$5B
        BCS     L1B59

L1B8E:
        STA     c64MacroId
        LDA     #$08
        JSR     vecSendByte
        LDA     #$20
        JSR     vecSendByte
        LDA     c64MacroId
        JSR     vecSendByte
        LDA     #$00
        JSR     vecSendByte
        BIT     L11D8
        BPL     L1BBD
        JSR     vecMacroRecClose
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6B
        JSR     vecSendByte
        LDA     #$00
        STA     L11D8

L1BBD:
        BIT     L11EC
        BPL     L1BD7
        JSR     vecMacroCloseRead
        LDA     #$00
        STA     L11EC
        LDA     #$10
        JSR     vecSendByte
        LDA     #$2E
        JSR     vecSendByte
        JSR     vecHideMsg

L1BD7:
        JSR     vecMacroOpenRead
        BCC     L1BEA
        LDA     #$02
        JSR     vecShowMsg

L1BE1:
        JSR     vecGetKey
        BCS     L1BE1

L1BE6:
        JSR     vecHideMsg
        RTS

L1BEA:
        BIT     STATUS
        BVS     L1BE6
        TXA
        PHA
        LDA     #$FF
        STA     L11EC
        LDA     #$10
        JSR     vecSendByte
        LDA     #$2C
        JSR     vecSendByte
        JSR     vecClearMsg
        LDA     #$0C
        JSR     vecShowMsg
        LDA     c64MacroId
        JSR     vecSendByte
        LDA     #$20
        JSR     vecSendByte
        PLA
        JSR     vecSendKey
        JSR     UNTLK
        RTS

c64MenuCapture:
; vector 20 $103C - menu 'C' (Capture): send $10 $4D, msg 5 "Capture-Modus ein - Ende: STOP-Taste", arm the capture flag and point the write pointer at c64BufStart
        JSR     vecHideMsg
        LDA     #$10
        JSR     vecSendByte
        LDA     #$4D
        JSR     vecSendByte
        LDA     #$05
        JSR     vecShowMsg
        LDA     #$FF
        STA     btxStatus
        STA     L11D9
        LDA     c64BufStart
        STA     c64BufWr
        LDA     c64BufStart+1
        STA     c64BufWrHi
        RTS

c64CaptureRun:
; vector 21 $103F - the capture engine: drain c64GetByte into the buffer until page $80 is reached, then msg 8 "Puffer voll - File?" and c64SaveBuffer
        JSR     vecGetByte
        BCS     L1C94
        LDY     #$00
        STA     (c64BufWr),Y
        INC     c64BufWr
        BNE     L1C55
        INC     c64BufWrHi
        LDA     c64BufWrHi
        CMP     c64BufEndPage
        BEQ     L1C58

L1C55:
        JMP     c64CaptureRun

L1C58:
        LDA     #$00
        STA     L11D9
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6D
        JSR     vecSendByte
        JSR     vecClearMsg
        LDA     #$08
        JSR     vecShowMsg
        LDA     c64BufWr
        STA     c64CapEnd
        LDA     c64BufWrHi
        STA     c64CapEnd+1
        JSR     vecSaveBuffer

L1C7C:
        LDA     btxXferEn
        BNE     L1C7C
        LDA     btxXferEn
        BNE     L1C7C

L1C86:
        LDA     btxFifoWr
        CMP     btxFifoWr
        BNE     L1C86
        STA     btxFifoRd
        JSR     vecHideMsg

L1C94:
        RTS

c64MenuDisplay:
; vector 22 $1042 - menu 'D' (Display): msg 6 "Capture-Puffer anzeigen", replay the captured bytes to the decoder, STOP aborts
        LDA     #$10
        JSR     vecSendByte
        LDA     #$4C
        JSR     vecSendByte
        LDA     #$06
        JSR     vecShowMsg
        LDA     c64BufStart
        STA     c64BufWr
        LDA     c64BufStart+1
        STA     c64BufWrHi
        LDA     #$00
        STA     L11DD

L1CB3:
        JSR     STOP
        BEQ     L1CC6
        LDA     c64BufWr
        CMP     c64CapEnd
        BNE     L1CD4
        LDA     c64BufWrHi
        CMP     c64CapEnd+1
        BNE     L1CD4

L1CC6:
        JSR     vecHideMsg
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6C
        JSR     vecSendByte
        RTS

L1CD4:
        LDA     L11DD
        CMP     #$11
        BNE     L1CE0
        LDA     #$05
        JSR     vecDelaySecs

L1CE0:
        LDY     #$00
        LDA     (c64BufWr),Y
        STA     L11DD
        JSR     vecSendByte
        INC     c64BufWr
        BNE     L1CF0
        INC     c64BufWrHi

L1CF0:
        JMP     L1CB3

c64MenuXfer:
