L237F:
        BIT     L11E8
        BPL     L2396
        CMP     #$59
        BEQ     L2394
        CMP     #$5A
        BEQ     L2394
        CMP     #$D9
        BEQ     L2394
        CMP     #$DA
        BNE     L2396

L2394:
        EOR     #$03

L2396:
        BIT     L11D8
        BPL     L23A8
        PHA
        JSR     vecMacroRecOpen
        PLA
        PHA
        JSR     CIOUT
        JSR     UNLSN
        PLA

L23A8:
        CMP     #$0D
        BNE     L23BA

L23AC:
        LDX     btxReg090
        CPX     btxReg090
        BNE     L23AC
        CPX     #$28
        BEQ     L23BA
        LDA     #$8D

L23BA:
        CLC
        RTS

L23BC:
        SEC
        RTS

L23BE:
        JSR     STOP
        BNE     L23C8
        LDA     #$00
        JMP     L23D7

L23C8:
        JSR     vecMacroTalk
        JSR     vecDiskGetByte
        PHP
        PHA
        JSR     UNTLK
        PLA
        PLP
        BVC     L23F8

L23D7:
        PHA
        LDA     #$00
        JSR     vecSendByte
        JSR     vecHideMsg
        LDA     #$00
        STA     L11EC
        LDA     #$10
        JSR     vecSendByte
        LDA     #$2E
        JSR     vecSendByte
        JSR     vecHideMsg
        JSR     vecMacroCloseRead
        PLA
        CLC
        RTS

L23F8:
        TXA
        CMP     #$01
        BNE     L2402
        JSR     vecWaitDecoder
        SEC
        RTS

L2402:
        CLC
        RTS

L2404:
        LDA     #$7F
        STA     $DC00
        LDA     $DC01
        CMP     #$FB
        PHP
        LDA     #$7F
        STA     $DC00
        PLP
        BNE     L2463
        LDA     #$02
        JSR     vecDelaySecs
        LDX     #$00

L241E:
        LDA     c64ExtraFile,X
        BEQ     L2429
        STA     L11BE,X
        INX
        BNE     L241E

L2429:
        STX     L11BC
        JSR     vecDiskOpenRead
        BCS     L2460
        STA     c64Ptr
        STA     c64BufWr
        JSR     vecDiskGetByte
        BVS     L2460
        STA     c64PtrHi
        STA     c64BufWrHi
        LDA     #$19
        JSR     vecShowMsg

L2443:
        JSR     vecDiskGetByte
        BVS     L2457
        BCS     L2460
        LDY     #$00
        STA     (c64Ptr),Y
        INC     c64Ptr
        BNE     L2454
        INC     c64PtrHi

L2454:
        JMP     L2443

L2457:
        JSR     vecDiskCloseRead
        JSR     vecHideMsg
        JMP     (c64BufWr)

L2460:
        JSR     vecDiskCloseRead

L2463:
        RTS

; Filename of the extra software: "BTX-EXTRA.MAS", null-terminated.
;
; Loaded from disk when the user picks Telesoft, which is what the status
; message "Zusatzsoftware wird geladen" refers to. It sits immediately after an
; RTS, so a linear sweep runs straight into it and disassembles the characters
; as instructions.
c64ExtraFile:
        FCC     "BTX-EXTRA.MAS"
        FCB     $00

c64ShowSplash:
; vector 54 $10A2 - print c64SplashText on the C64 screen, then set the background and fill colour RAM
        LDA     #c64SplashText&255
        STA     INBIT
        LDA     #c64SplashText>>8
        STA     BITCI

L247A:
        LDY     #$00
        LDA     (INBIT),Y
        BEQ     L248B
        JSR     BSOUT
        INC     INBIT
        BNE     L247A
        INC     BITCI
        BNE     L247A

L248B:
        LDA     #$0F
        STA     $D021
        LDY     #$00
        LDA     #$0B

L2494:
        STA     $D800,Y
        STA     $D900,Y
        STA     $DA00,Y
        STA     $DB00,Y
        INY
        BNE     L2494
        RTS

; Startup screen text, PETSCII, ROM $C84C-$C94C (runtime $24A4-$25A4).
;
; Opens with $0E $08 $93 - switch to lower case, disable the Shift+Commodore
; case toggle, clear screen - then the message, with $0D for line breaks and
; $11 for cursor-down. Letters that appear as high-bit values ($CD, $C2, $D3 and
; so on) are shifted PETSCII, so the text reads:
;
;     BILDSCHIRMTEXT
;     BITTE STECKEN SIE IHREN MONITOR
;     AN DAS BTX-MODUL AN,
;     ODER WAEHLEN SIE DIE EINGE-
;     SCHRAENKTE TEXTDARSTELLUNG
;     MIT "<F7> S".
;     SIE VERLASSEN BTX MIT "<F7> Q".
;
; So the module tells the user to plug a monitor into the decoder itself, and
; offers a reduced text-only mode on the C64 screen as the alternative - which
; is what the separate 8x10 narrow font at $9E00 is for.
c64SplashText:
        CHARSET $41,$5A,$C1
        CHARSET $61,$7A,$41
        FCB     $0E,$08,$93,$97,$11,$11,$11
        FCC     "            Bildschirmtext"
        FCB     $0D,$11,$11,$11,$11
        FCC     "   Bitte stecken Sie Ihren Monitor"
        FCB     $0D
        FCC     "   an das Btx-Modul an,"
        FCB     $0D,$0D
        FCC     "   oder waehlen Sie die einge-"
        FCB     $0D
        FCC     "   schraenkte Textdarstellung"
        FCB     $0D
        FCC     "   mit "
        FCB     $22
        FCC     "<F7> S"
        FCB     $22,$2E,$0D,$0D
        FCC     "   Sie verlassen Btx mit "
        FCB     $22
        FCC     "<F7> Q"
        FCB     $22,$2E,$0D,$0D,$0D,$0D,$0D
        FCC     "----------------------------------------"
        FCB     $00
        CHARSET

c64PlotChar:
; vector 55 $10A5 - poke screen code A at column Y of row X, using the KERNAL line-address tables at $ECF0 and LDTB1
        PHP
        SEI
        PHA
        TXA
        PHA
        LDA     $ECF0,Y
        STA     INBIT
        LDA     >$00D9,Y
        AND     #$0F
        STA     BITCI
        PLA
        TAY
        PLA
        STA     (INBIT),Y
        PLP
        RTS

c64SetCursor:
; vector 56 $10A8 - set PNTR/TBLX and call STUPT; X = $FF instead re-enables the cursor blink
        PHP
        SEI
        CPX     #$FF
        BEQ     L25D0
        STX     PNTR
        STY     TBLX
        LDA     #$00
        STA     BLNSW
        JSR     STUPT
        PLP
        RTS

L25D0:
        LDA     #$01
        STA     BLNSW
        PLP
        RTS

c64DiskShowError:
; vector 38 $1072 - read the DOS error channel, msg 9, and forward the message text to the decoder for display. C=1 when the code is not 00
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        JSR     TALK
        BIT     STATUS
        BMI     L2650
        LDA     #$6F
        STA     SA
        JSR     TKSA
        JSR     vecClearMsg
        LDA     #$09
        JSR     vecShowMsg
        LDA     #$00
        STA     L11DC
        JSR     vecDiskGetByte
        BCS     L2648
        BVS     L2648
        CMP     #$30
        BEQ     L2609
        LDA     #$FF
        STA     L11DC

L2609:
        JSR     vecDiskGetByte
        BCS     L2648
        BVS     L2648
        CMP     #$30
        BEQ     L261C
        LDA     #$FF
        ORA     L11DC
        STA     L11DC

L261C:
        JSR     vecDiskGetByte
        BCS     L2648
        BVS     L2648

L2623:
        JSR     vecDiskGetByte
        BCS     L2648
        BVS     L2648
        CMP     #$2C
        BEQ     L263C
        TAX
        LDA     STATUS
        LSR     A
        LSR     A
        BCS     L2623
        TXA
        JSR     vecSendByte
        JMP     L2623

L263C:
        LDA     #$00
        JSR     vecSendByte

L2641:
        JSR     vecDiskGetByte
        BCS     L2648
        BVC     L2641

L2648:
        JSR     UNTLK
        BIT     L11DC
        BPL     L2652

L2650:
        SEC
        RTS

L2652:
        CLC
        RTS

c64DiskCheckError:
; vector 39 $1075 - read and discard the DOS error channel; C=1 when the code is not 00
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        JSR     TALK
        LDX     STATUS
        BNE     L26A5
        LDA     #$6F
        STA     SA
        JSR     TKSA
        LDX     STATUS
        BNE     L26A5
        LDA     #$00
        STA     L11DC
        JSR     vecDiskGetByte
        BCS     L269D
        BVS     L269D
        CMP     #$30
        BEQ     L2683
        LDA     #$FF
        STA     L11DC

L2683:
        JSR     vecDiskGetByte
        BCS     L269D
        BVS     L269D
        CMP     #$30
        BEQ     L2696
        LDA     #$FF
        ORA     L11DC
        STA     L11DC

L2696:
        JSR     vecDiskGetByte
        BCS     L269D
        BVC     L2696

L269D:
        JSR     UNTLK
        BIT     L11DC
        BPL     L26A7

L26A5:
        SEC
        RTS

L26A7:
        CLC
        RTS

c64MacroRecStart:
; vector 47 $108D - OPEN "@:BTX-MAK-<id>,S,W" on device 8 channel 5 to begin recording a macro; msg $0D on failure
        LDY     #$0F
        STY     FNLEN
        LDA     #$02
        STA     LA
        LDA     #$08
        STA     FA
        LDA     #$65
        STA     SA
        LDA     #c64MacroFile&255
        STA     FNADR
        LDA     #c64MacroFile>>8
        STA     FNADR+1
        LDA     #$00
        STA     STATUS
        JSR     vecOpenChannel
        BCC     L26D1
        LDA     #$0D
        JSR     vecShowMsg
        SEC
        RTS

L26D1:
        JSR     vecDiskShowError
        BCS     L26D7
        RTS

L26D7:
        SEC
        RTS

c64MacroRecOpen:
; vector 34 $1066 - LISTN device 8 channel 5, the macro record file, and emit a $01 filler whenever the decoder's line counter btxReg011 has advanced
        LDA     #$02
        STA     LA
        LDA     #$08
        STA     FA
        LDA     #$65
        STA     SA
        LDA     FA
        JSR     LISTN
        LDA     SA
        JSR     SECND

L26EF:
        LDA     btxReg090
        CMP     btxReg090
        BNE     L26EF
        CMP     #$28
        BEQ     L2709

L26FB:
        LDA     btxReg011
        CMP     btxReg011
        BNE     L26FB
        STA     L11ED
        JMP     L271E

L2709:
        LDA     btxReg011
        CMP     btxReg011
        BNE     L2709
        CMP     L11ED
        BEQ     L271E
        LDA     #$01
        JSR     CIOUT
        INC     L11ED

L271E:
        RTS

c64MacroTalk:
; vector 35 $1069 - TALK device 8 channel 6: make the macro file the talker for playback
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        JSR     TALK
        LDA     #$66
        STA     SA
        JSR     TKSA
        RTS

c64OpenPrgWrite:
; vector 60 $10B4 - append ",P,W" to the filename and OPEN it on device 8 channel 4, then share c64OpenSeqWrite's tail
        LDY     L11BC
        LDA     #$2C
        STA     L11BE,Y
        INY
        LDA     #$50
        STA     L11BE,Y
        INY
        LDA     #$2C
        STA     L11BE,Y
        INY
        LDA     #$57
        STA     L11BE,Y
        INY
        STY     FNLEN
        JMP     L276F

c64OpenSeqWrite:
; vector 48 $1090 - append ",S,W" to the filename and OPEN it on device 8 channel 4
        LDY     L11BC
        LDA     #$2C
        STA     L11BE,Y
        INY
        LDA     #$53
        STA     L11BE,Y
        INY
        LDA     #$2C
        STA     L11BE,Y
        INY
        LDA     #$57
        STA     L11BE,Y
        INY
        STY     FNLEN

L276F:
        JSR     UNLSN
        JSR     UNTLK
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        LDA     #L11BE&255
        STA     FNADR
        LDA     #L11BE>>8
        STA     FNADR+1
        LDA     #$00
        STA     STATUS
        JSR     vecOpenChannel
        BCS     L27AD
        JSR     vecDiskShowError
        BCC     L2795
        SEC
        RTS

L2795:
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        LDA     FA
        JSR     LISTN
        LDA     SA
        JSR     SECND
        LDA     FA
        STA     DFLTO
        CLC
        RTS

L27AD:
        JSR     vecClearMsg
        LDA     #$0D
        JSR     vecShowMsg
        SEC
        RTS

c64MacroOpenRead:
; vector 50 $1096 - open "@:BTX-MAK-<id>" on device 8 channel 6 for reading, via the shared tail of c64DiskOpenRead
        LDA     #$00
        STA     STATUS
        LDA     #$03
        STA     LA
        LDA     #$08
        STA     FA
        LDA     #$66
        STA     SA
        LDA     #c64MacroFile&255
        STA     FNADR
        LDA     #c64MacroFile>>8
        STA     FNADR+1
        LDA     #$0B
        STA     FNLEN
        JMP     L28C3

c64MacroDir:
; vector 51 $1099 - send ceptMacroDir ("Makro-Verzeichnis") and list every macro '0'-'9' then 'A'-'Z' with c64MacroDirLine
        BIT     L11EC
        BMI     L2845
        LDA     #$10
        JSR     vecSendByte
        LDA     #$4C
        JSR     vecSendByte
        LDA     c64MacroDirPtr
        STA     c64Ptr
        LDA     c64MacroDirPtr+1
        STA     c64PtrHi

L27EF:
        LDY     #$00
        LDA     (c64Ptr),Y
        BEQ     L2801
        JSR     vecSendByte
        INC     c64Ptr
        BNE     L27EF
        INC     c64PtrHi
        JMP     L27EF

L2801:
        LDA     #$30
        STA     c64MacroId

L2806:
        JSR     vecMacroDirLine
        BCS     L2833
        JSR     STOP
        BEQ     L2833
        INC     c64MacroId
        LDA     c64MacroId
        CMP     #$3A
        BNE     L2806
        LDA     #$41
        STA     c64MacroId

L281F:
        JSR     vecMacroDirLine
        BCS     L2833
        JSR     STOP
        BEQ     L2833
        INC     c64MacroId
        LDA     c64MacroId
        CMP     #$5B
        BNE     L281F

L2833:
        JSR     STOP
        BEQ     L2833
        JSR     vecDiskCheckError
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6C
        JSR     vecSendByte

L2845:
        RTS

c64MacroDirLine:
; vector 52 $109C - one directory line: "<id>: " followed by the first 17 characters of that macro file, padded with spaces, or dashes when it does not exist
        LDA     c64MacroId
        JSR     vecSendByte
        LDA     #$3A
        JSR     vecSendByte
        LDA     #$20
        JSR     vecSendByte
        LDA     #$11
        STA     L11BA
        JSR     vecMacroOpenRead
        BCS     L287B
        TXA
        JSR     vecSendKey
        DEC     L11BA

L2867:
        JSR     vecDiskGetByte
        BCS     L28A5
        BVS     L2896
        CMP     #$00
        BEQ     L2896
        JSR     vecSendKey
        DEC     L11BA
        BNE     L2867
        RTS

L287B:
        LDA     #$2D
        JSR     vecSendByte
        DEC     L11BA
        LDA     L11BA
        CMP     #$0B
        BNE     L287B

L288A:
        LDA     #$20
        JSR     vecSendByte
        DEC     L11BA
        BNE     L288A
        CLC
        RTS

L2896:
        LDA     #$20
        JSR     vecSendByte
        DEC     L11BA
        BNE     L2896
        JSR     vecMacroCloseRead
        CLC
        RTS

L28A5:
        JSR     L2896
        SEC
        RTS

c64DiskOpenRead:
; vector 16 $1030 - open the named file on device 8 channel 4 for reading, TALK/TKSA, return the first byte in X. Shares the tail with c64MacroOpenRead
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        LDA     #L11BE&255
        STA     FNADR
        LDA     #L11BE>>8
        STA     FNADR+1
        LDA     L11BC
        STA     FNLEN

L28C3:
        JSR     UNTLK
        JSR     UNLSN
        JSR     vecOpenChannel
        BCS     L28EB
        LDA     SA
        STA     L11BB
        JSR     vecDiskCheckError
        BCS     L28EB
        LDA     FA
        JSR     TALK
        LDA     L11BB
        STA     SA
        JSR     TKSA
        JSR     vecDiskGetByte
        TAX
        CLC
        RTS

L28EB:
        SEC
        RTS

c64DiskGetByte:
; vector 17 $1033 - ACPTR one byte with a STOP check; C=1 on abort, V mirrors the EOI bit of STATUS
        LDA     #$00
        STA     STATUS

L28F1:
        LDA     #$FD
        AND     STATUS
        STA     STATUS
        JSR     STOP
        BEQ     L290B
        JSR     ACPTR
        TAX
        LDA     STATUS
        LSR     A
        LSR     A
        BCS     L28F1
        TXA
        BIT     STATUS
        CLC
        RTS

L290B:
        SEC
        RTS

c64CloseWrite:
; vector 33 $1063 - CLOSE device 8 channel 4: finish the file opened by c64OpenSeqWrite or c64OpenPrgWrite
        JSR     UNLSN
        LDA     #$08
        JSR     LISTN
        LDA     #$E4
        JSR     SECND
        JSR     UNLSN
        RTS

c64MacroRecClose:
; vector 36 $106C - terminate the macro record file with a $00 and CLOSE device 8 channel 5
        JSR     vecMacroRecOpen
        LDA     #$00
        JSR     CIOUT
        JSR     UNLSN
        LDA     #$08
        JSR     LISTN
        LDA     #$E5
        JSR     SECND
        JSR     UNLSN
        RTS

c64MacroCloseRead:
; vector 37 $106F - CLOSE device 8 channel 6: end macro playback
        LDA     #$66
        STA     SA
        LDA     #$08
        STA     FA
        JSR     CLSEI
        RTS

c64DiskCloseRead:
; vector 18 $1036 - UNTLK and CLOSE device 8 channel 4
        JSR     UNTLK
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        JSR     CLSEI
        RTS

c64OpenChannel:
; vector 59 $10B1 - the shared open primitive: LISTN, SECND with SA | $F0, then fall into the KERNAL OPEN body at OP35
        LDA     #$00
        STA     STATUS
        LDA     FA
        JSR     LISTN
        LDA     STATUS
        BMI     L296A
        LDA     SA
        ORA     #$F0
        JSR     SECND
        LDA     STATUS
        BPL     L296C

L296A:
        SEC
        RTS

L296C:
        JMP     OP35

ceptMacroDir:
        FCB     $1F,$2F,$41,$9B,$31,$40,$1B,$23,$20,$57,$9B,$30,$40,$1F
        FCC     "AA   "
        FCB     $8F,$08
        FCC     "Makro-Verzeichnis"
        FCB     $0D,$0A,$0A,$0A,$0A,$00

c64MenuTelesoft:
; vector 57 $10AB - menu 'T' (Telesoft): msg $1A "Telesoftware: File?", open a PRG file and run the telesoftware download decoder
        LDA     L11EC
        ORA     L11D8
        BEQ     L29B1
        LDA     #$1E
        JSR     vecShowMsg

L29A8:
        JSR     vecGetKey
        BCS     L29A8
        JSR     vecHideMsg
        RTS

L29B1:
        JSR     vecClearMsg
        LDA     #$1A
        JSR     vecShowMsg
        LDA     #$13
        JSR     vecInputLine
        BCC     L29C4
        JSR     vecHideMsg
        RTS

L29C4:
        JSR     vecOpenPrgWrite
        BCC     L29D7
        LDA     #$17
        JSR     vecShowMsg

L29CE:
        JSR     vecGetKey
        BCS     L29CE
        JSR     vecHideMsg
        RTS

L29D7:
        LDA     #$1B
        JSR     vecShowMsg
        LDA     #$10
        JSR     vecSendByte
        LDA     #$4D
        JSR     vecSendByte
        LDA     c64BufStart
        STA     c64BufWr
        STA     c64BufRd
        STA     c64CapEnd
        LDA     c64BufStart+1
        STA     c64BufWrHi
        STA     c64BufRdHi
        STA     c64CapEnd+1

L29FA:
        JSR     vecTelesoftByte
        BCC     L29FA

L29FF:
        LDA     #$00
        STA     L11F0
        JSR     vecTelesoftByte
        BCS     L29FF
        CMP     #$3C
        BEQ     L2A11
        CMP     #$3E
        BNE     L29FA

L2A11:
        JSR     vecTelesoftByte
        BCS     L29FF
        CMP     #$27
        BNE     L2A1D
        JMP     L2A4A

L2A1D:
        AND     #$E0
        CMP     #$40
        BNE     L29FA
        LDA     #$FF
        STA     L11F0
        LDA     #$00
        STA     L11F1
        JSR     vecTelesoftByte
        BCS     L29FF
        CMP     #$43
        BNE     L2A39
        JMP     L2ABD

L2A39:
        CMP     #$45
        BNE     L2A40
        JMP     L2ABD

L2A40:
        CMP     #$47
        BNE     L2A47
        JMP     L2AC0

L2A47:
        JMP     L29FA

L2A4A:
        JSR     vecTelesoftByte
        BCS     L2ABA
        JSR     vecTelesoftByte
        BCS     L2ABA
        AND     #$0F
        BEQ     L2AB7
        STA     L11F5

L2A5B:
        JSR     vecTelesoftByte
        BCS     L2ABA
        DEC     L11F5
        BEQ     L2AB7
        CMP     #$22
        BEQ     L2A8C
        JSR     vecTelesoftByte
        BCS     L2ABA
        DEC     L11F5
        BEQ     L2AB7
        AND     #$0F
        BEQ     L2A5B
        STA     L11F6

L2A7A:
        JSR     vecTelesoftByte
        BCS     L29FF
        DEC     L11F5
        BEQ     L2AB7
        DEC     L11F6
        BEQ     L2A5B
        JMP     L2A7A

L2A8C:
        JSR     vecTelesoftByte
        BCS     L2ABA
        JSR     vecTelesoftByte
        CMP     #$42
        BNE     L2AA0
        LDA     #$1C
        JSR     vecShowMsg
        JMP     L2AB7

L2AA0:
        LDA     #$10
        JSR     vecSendByte
        LDA     #$6D
        JSR     vecSendByte
        LDA     #$1D
        JSR     vecShowMsg

L2AAF:
        JSR     vecGetKey
        BCS     L2AAF
        JMP     L2AEE

